'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['resolvePass']);
const { resolvePass } = api;

const members = [
  { memberId: 'm1', passes: ['alpha', 'shared'], role: 'admin' },
  { memberId: 'm2', passes: ['beta'] }
];
const before = members.map(member => ({ ...member, passes: member.passes.slice() }));
let decoded = [];
const success = resolvePass(members, 'Pass shared', credential => {
  decoded.push(credential);
  return { memberId: 'm1', ignored: true };
});
assert.deepStrictEqual(decoded, ['shared']);
assert.strictEqual(success.ok, true);
assert.strictEqual(success.credential, 'shared');
assert.deepStrictEqual(success.member, members[0]);
assert.notStrictEqual(success.member, members[0]);
assert.notStrictEqual(success.member.passes, members[0].passes);
success.member.passes.push('changed');
success.member.memberId = 'changed';
assert.deepStrictEqual(members, before);

const unauthorized = { ok: false, reason: 'unauthorized' };
for (const auth of [null, '', 'Pass', 'Pass ', 'Pass  alpha', ' Pass alpha', 'Pass alpha ', 'Bearer alpha', 'pass alpha']) {
  let calls = 0;
  assert.deepStrictEqual(resolvePass(members, auth, () => { calls += 1; return { memberId: 'm1' }; }), unauthorized);
  assert.strictEqual(calls, 0);
}
assert.deepStrictEqual(resolvePass(members, 'Pass alpha', () => { throw new Error('bad pass'); }), unauthorized);
for (const decodedValue of [null, {}, { memberId: '' }, { memberId: 1 }]) {
  assert.deepStrictEqual(resolvePass(members, 'Pass alpha', () => decodedValue), unauthorized);
}
assert.deepStrictEqual(resolvePass(members, 'Pass alpha', () => ({ memberId: 'missing' })), unauthorized);
assert.deepStrictEqual(resolvePass(members, 'Pass beta', () => ({ memberId: 'm1' })), unauthorized);
assert.deepStrictEqual(resolvePass([], 'Pass anything', () => ({ memberId: 'm1' })), unauthorized);

for (const badMembers of [null, {}, [null], [{ memberId: '', passes: [] }], [{ memberId: 'm', passes: 'x' }], [{ memberId: 'm', passes: [''] }], [{ memberId: 'm', passes: [1] }]]) {
  assert.throws(() => resolvePass(badMembers, 'invalid', () => ({ memberId: 'm' })), TypeError);
}
assert.throws(() => resolvePass([
  { memberId: 'm', passes: [] },
  { memberId: 'm', passes: [] }
], 'invalid', () => ({ memberId: 'm' })));
assert.throws(() => resolvePass([], 'invalid', null), TypeError);

let decoderCalled = false;
assert.throws(() => resolvePass([{ memberId: 'ok', passes: [] }, null], 'invalid', () => {
  decoderCalled = true;
  return { memberId: 'ok' };
}), TypeError);
assert.strictEqual(decoderCalled, false);

